"""Load the reference frames in tests/fixtures/ (generated by tools/extract_fixtures.py)."""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..'))


def load(name):
    """List of messages; a message is a list of 64-byte packets."""
    out = []
    with open(os.path.join(HERE, 'fixtures', name)) as f:
        for line in f:
            line = line.partition('#')[0].strip()
            if line:
                out.append([bytes.fromhex(p) for p in line.split()])
    return out
